#题意
-------


**题目描述**

>从上往下打印出二叉树的每个节点，同层节点从左至右打印。

#分析
-------
其实就是层次遍历，这个我们在我之前的一篇博客里面将的很清楚了

>[二叉树的遍历详解（前序中序后序层次-递归和非递归）](http://blog.csdn.net/gatieme/article/details/51163010#t10)

其中调试的时候使用了

>[剑指Offer--006-重构二叉树](http://blog.csdn.net/gatieme/article/details/51108612)来辅助我们通过前序和中序遍历的序列来生成二叉树

直接贴代码，只需要直接将我们层次遍历输出过程，变成将输入压入vector中即可

```cpp
#include <iostream>
#include <vector>
#include <deque>
#include <queue>

using namespace std;

//  调试开关
#define __tmain main

#ifdef __tmain

#define debug cout

#else

#define debug 0 && cout

#endif // __tmain


#define undebug 0 && cout


#ifdef __tmain
struct TreeNode
{
	int val;
	struct TreeNode *left;
	struct TreeNode *right;

	TreeNode(int x)
	:val(x), left(NULL), right(NULL)
    {
	}
};
#endif // __tmain



class Solution
{
    vector<int> res;
public:
    vector<int> PrintFromTopToBottom(TreeNode *root)
    {
        ///  方法1  -=>  循环调用递归打印每一层
        LevelOrder(root);

        ///  方法2  -=>  使用两个双端队列
        LevelOrderDev(root);

        ///  方法3  -=>  使用双指针标识当前指针和结束
        LevelOrderUsePoint(root);

        ///  方法4  -=>  使用aprent和childzsizesize标识前一层和当前层的节点个数
        LevelOrderUseSize(root);

        ///  方法4  -=>  在队列中插入结束标识来标识当前层结束
        LevelOrderUseEnd(root);
        return this->res;
    }

    /// 打印某一层的节点，递归实现
    int PrintLevel(TreeNode *root, int level)
    {
        if(root == NULL || level < 0)
        {
            return 0;
        }
        else if(level == 0)
        {
            debug <<root->val;
            res.push_back(root->val);        /// add for result in vector

            return 1;
        }
        else
        {
            return PrintLevel(root->left, level - 1) + PrintLevel(root->right, level - 1);
        }
    }

    ///  循环每层输出其节点，调用递归函数
    void LevelOrder(TreeNode *root)
    {
        res.clear( );           /// add for result in vector
        if(root == NULL)
        {
            return;
        }
        for(int level = 0; ; level++)
        {
            if(PrintLevel(root, level) == 0)
            {
                break;
            }
            debug <<endl;
        }
    }

    //////////////////////////
    ///  使用两个双端队列
    //////////////////////////
    void LevelOrderDev(TreeNode *root)
    {
        res.clear( );           /// add for result in vector

        /// deque双端队列，
        /// 支持迭代器，有push_back()方法，
        /// 跟vector差不多，比vector多了个pop_front,push_front方法

        deque<TreeNode *> qFirst, qSecond;
        qFirst.push_back(root);

        while(qFirst.empty( ) != true)
        {
            while (qFirst.empty( ) != true)
            {
                TreeNode *temp = qFirst.front( );
                qFirst.pop_front( );

                debug << temp->val;
                res.push_back(temp->val);        /// add for result in vector


                if (temp->left != NULL)
                {
                    qSecond.push_back(temp->left);
                }
                if (temp->right != NULL)
                {
                    qSecond.push_back(temp->right);
                }
            }
            debug << endl;
            qFirst.swap(qSecond);

        }
    }


    //////////////////////////
    ///  使用双指针标识当前指针和结束
    //////////////////////////
    void LevelOrderUsePoint(TreeNode *root)
    {
        res.clear( );           /// add for result in vector

        vector<TreeNode*> vec;
        vec.push_back(root);

        int cur = 0;
        int end = 1;

        while (cur < vec.size())
        {
            end = vec.size();       ///  新的一行访问开始，重新定位end于当前行最后一个节点的下一个位置

            while (cur < end)
            {
                debug << vec[cur]->val;  ///  访问节点
                res.push_back(vec[cur]->val);        /// add for result in vector

                if (vec[cur]->left != NULL) ///  压入左节点
                {
                    vec.push_back(vec[cur]->left);

                }
                if (vec[cur]->right != NULL)    ///  压入右节点
                {
                    vec.push_back(vec[cur]->right);
                }
                cur++;
            }
            debug << endl;
        }
    }


    //////////////////////////
    ///  使用aprent和childzsizesize标识前一层和当前层的节点个数
    //////////////////////////
    void LevelOrderUseSize(TreeNode *root)
    {
        res.clear( );           /// add for result in vector

        int parentSize = 1, childSize = 0;
        TreeNode *temp = NULL;

        queue<TreeNode *> q;
        q.push(root);
        while(q.empty( ) != true)
        {
            temp = q.front( );
            debug <<temp->val;
            res.push_back(temp->val);        /// add for result in vector

            q.pop( );

            if (temp->left != NULL)
            {
                q.push(temp->left);

                childSize++;
            }
            if (temp->right != NULL)
            {
                q.push(temp->right);
                childSize++;
            }

            parentSize--;
            if (parentSize == 0)
            {
                parentSize = childSize;
                childSize = 0;
                debug << endl;
            }

        }
    }

    //////////////////////////
    ///  在队列中插入结束标识来标识当前层结束
    //////////////////////////
    void LevelOrderUseEnd(TreeNode *root)
    {
        res.clear( );           /// add for result in vector

        queue<TreeNode *> q;

        q.push(root);
        q.push(NULL);

        while(q.empty( ) != true)
        {
            TreeNode* node = q.front();
            q.pop();

            if (node)
            {
                debug << node->val;
                res.push_back(node->val);        /// add for result in vector

                if (node->left != NULL)
                {
                    q.push(node->left);
                }
                if (node->right != NULL)
                {
                    q.push(node->right);
                }
            }
            else if (q.empty( ) != true)
            {
                q.push(NULL);
                debug << endl;
            }
        }
    }


    struct TreeNode* reConstructBinaryTree(vector<int> pre,vector<int> in)
    {
        //  前序遍历的长度跟中序遍历的长度应该相同
        if(pre.size( ) != in.size( ))
        {
            undebug <<"the length of PRE and IN should be smae" <<endl;
            return NULL;
        }

        // 长度不能为0
        int size = pre.size( );
        if(size == 0)
        {
            undebug <<"it's a NULL tree(length = 0)" <<endl;
            return NULL;
        }

        int length = pre.size( );
        undebug <<"the length of your tree = " <<length <<endl;
        int value = pre[0];      //  前序遍历的第一个结点是根节点
        TreeNode *root = new TreeNode(value);

        undebug <<"the root is" <<root->val <<endl;
        //  在中序遍历中查找到根的位置
        int rootIndex = 0;
        for(rootIndex = 0; rootIndex < length; rootIndex++)
        {
            if(in[rootIndex] == value)
            {
                undebug <<"find the root at " <<rootIndex <<" in IN" <<endl;
                break;
            }
        }
        if(rootIndex >= length)
        {
            undebug <<"can't find root (value = " <<value <<") in IN" <<endl;
            return NULL;
        }

        ///  区分左子树和右子树
        ///  中序遍历中, 根左边的就是左子数, 右边的就是右子树
        ///  前序遍历中, 根后面是先遍历左子树, 然后是右子树

        ///  首先确定左右子树的长度, 从中序遍历in中确定
        int leftLength = rootIndex;
        int rightLength = length - 1 - rootIndex;
        undebug <<"left length = " <<leftLength <<", rightLength = " <<rightLength <<endl;
        vector<int> preLeft(leftLength), inLeft(leftLength);
        vector<int> preRight(rightLength), inRight(rightLength);
        for(int i = 0; i < length; i++)
        {
            if(i < rootIndex)
            {
                //  前序遍历的第一个是根节点, 根后面的(leftLegnth = rootIndex) - 1个节点是左子树, 因此是i+1
                preLeft[i] = pre[i + 1];
                //  中序遍历前(leftLength = rootIndex) - 1个节点是左子树, 第rootIndex个节点是根
                inLeft[i] = in[i];
                undebug <<preLeft[i] <<inLeft[i] <<" ";

            }
            else if(i > rootIndex)
            {
                //  前序遍历的第一个是根节点, 根后面的(leftLegnth = rootIndex) - 1个节点是左子树, 后面是右子树
                preRight[i - rootIndex - 1] = pre[i];
                //  中序遍历前(leftLength = rootIndex) - 1个节点是左子树, 第rootIndex个节点是根, 然后是右子树
                inRight[i - rootIndex - 1] = in[i];
                undebug <<preRight[i - rootIndex - 1] <<inRight[i - rootIndex - 1] <<" ";

            }
        }
        undebug <<endl <<"the left tree" <<endl;
        for(int i = 0; i < leftLength; i++)
        {
            undebug <<preLeft[i] <<inLeft[i] <<" ";
        }
        undebug <<endl;
        undebug <<"the right tree" <<endl;
        for(int i = 0; i < rightLength; i++)
        {
            undebug <<preRight[i] <<inRight[i] <<" ";
        }
        undebug <<endl;


        root->left = reConstructBinaryTree(preLeft, inLeft);
        root->right = reConstructBinaryTree(preRight, inRight);

        return root;
    }



};

int __tmain( )
{
    int pre[] = { 1, 2, 4, 7, 3, 5, 6, 8 };
    int in[] = { 4, 7, 2, 1, 5, 3, 8, 6 };

    vector<int> preOrder(pre, pre + 8);
    vector<int>  inOrder( in,  in + 8);

    Solution solu;
    TreeNode *root = solu.reConstructBinaryTree(preOrder, inOrder);
    solu.PrintFromTopToBottom(root);

    return 0;
}
```

Q:

CSS Wordpress Blog on Iphone

I am working on this wordpress blog http://www.taranmarlowjewelry.com/?page_id=7 (looks fine on a normal web broswer) I tried to edit the CSS so it looks good on an iphone...I added these lines in my iphone css file
.wrapper{
    position:relative;
    width:840px;
    margin:0 auto;
}

.blog #page{
    width:840px !important;
}

.blog #main{
    width:840px !important;
}

.blog #primary {
    width:220px !important;
}

.blog #content {
    width: 220px !important;
}

.blog #secondary {
    width:200px !important;
    float:right !important;
}

but there is a massive space between the blog and the sidebar and the width of this page is too wide, while my home, about page look good with the .wrapper at a width of 840px;
What is going wrong here?

A:

Have you tried using initial scale? 
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">

Add that in and adjust your CSS accordingly.

Q:

JQuery in a Visual WebPart won't load on the page with the webpart

Hey I have a bunch of JavaScript/Jquery code that works really well when I use a Content-Editor webpart, but does not execute when I add the same code to the VisualWebPart mark up.
I am referencing the JavaScript in the following way for both: 
<script src="http://ajax.googleapis.com/ajax/libs/jquery/1.3.2/jquery.min.js" type="text/javascript"></script>

<script type="text/javascript">
//Code here
</script>

Any idea why my JQuery code is not being recognized? (Yes I am using the $(document).ready(function() { .. }) )
Note: The JQuery code is not loaded on the page
I am fairly new to SharePoint development, visual webparts in particular. If you could help out I'd truly appreciate it. 
Thank You,
MyName.

<script src="http://ajax.googleapis.com/ajax/libs/jquery/1.3.2/jquery.min.js" type="text/javascript"></script>
<script type="text/javascript">
    $(document).ready(function () {

        alert('test!'); 

        //move he last list item before the first item. The purpose of this is if the user clicks to slide left he will be able to see the last item.
        $('#carousel_ul li:first').before($('#carousel_ul li:last'));

... more Code

    });
</script>

A:

At least you should use the following approach instead of jquery ready function:
<script type="text/javascript"> 
function TheFunctionToDoTheWork() 
{
    // Do the work here
}

// "Subscribe to the SharePoint "page load"
_spBodyOnLoadFunctionNames.push('TheFunctionToDoTheWork');
</script>

The document.ready in many cases fires too early in the SharePoint page cycle. In the example above you can see the SharePoint interface for "subscribing" to the page loaded event in the SharePoint point of view.

A:

May be another jquery version loaded before yours? and conflict appear...

Q:

How to use @Where in Hibernate

Searched for a few hours, but I'm stuck in a my learning curve for PlayFramework with JPA. I'm building a sample website where posts can be made. But these posts can have the states:

PostDraft (post is a draft, do not publish)
PostPublished (post can be published)

These states are stored in a seperate table. Obviously, the draft state posts should not be visible yet.
So I have these classes:

Page class (getting the page information from table, 1 page can have multiple posts)
Posts class (posts can be in draft and published)

In my page class I have:
@Column(name="POSTS_REF")
@Where(clause="PostPublished")
private List<Posts> userPosts;

But this is not working! So, how can I specifify a where clause, to load only the posts that are in published state without using JPQL??
Thanks!
UPDATE: 2011-10-11
Table: Posts with columns:
 - id
 - title
 - state_ref  (reference to the ID of States table)
 - content
Table: States with columns:
 - id
 - statename
So I want to say something like:
select * 
from posts inner join states on posts.state_ref = states.id
where states.statename = 'PostPublished'

UPDATE 2011-10-13
This is my current modification, in my page class: but it does not work either.
/** link to the states */
@JoinColumn(name = "STATES_REF")
@OneToOne
@Where(clause = "states.statename = 'PostPublished'")
public MyState state;

UPDATE 2012-02-13
Emt's answer worked for me after all.

A:

Try something like:
@Column(name="POSTS_REF")
@Where(clause="state='PostPublished'")
private List<Posts> userPosts;

or 
@Column(name="POSTS_REF")
@Where(clause="PostPublished=true")
private List<Posts> userPosts;

depending on the status field type on your Post entity.

A:

The where clause must be a complete condition - something like this.   Assuming that state is a property on the post.
@Column(name="POSTS_REF")
@Where(clause="state = 'PostPublished'")
private List<Posts> userPosts;

EDIT
Based on the data model - the following should work.  I wouldn't recommend using it. Don't map the posts collection - just have a reference to Page from the POsts class, add a method to your DAO to retrieve the published posts for a page by using HQL or criteria query.
@Column(name="POSTS_REF")
@Where(clause="exists (select id from states where state_ref = states.id and states.statename = 'PostPublished')")
private List<Posts> userPosts;

